mapper.select:
SELECT w.warehouse_id, w.tenant_id, w.warehouse_nm, w.use_at, w.created_by, w.created_at, w.updated_by, w.updated_at FROM tb_warehouse w WHERE w.tenant_id = #{tenantId}
AND w.use_at = #{useAt}
ORDER BY w.warehouse_nm ASC, w.warehouse_id ASC

SELECT warehouse_id
FROM tb_warehouse
WHERE tenant_id = #{tenantId}
  AND warehouse_nm = #{warehouseNm}

mapper.delete:
DELETE FROM tb_warehouse
WHERE warehouse_id = #{warehouseId}
  AND tenant_id = #{tenantId}
